Read file /Users/alessandro.cuppari/.gitbutler-worktrees/dhc-dashboard/feature-ale-449-notification-recovery/apps/web/src/lib/components/training-announcements/AnnouncementSheet.svelte, lines 1-579
1: <!--
2: 	Create or edit one Training Announcement (ALE-330).
3: 
4: 	The API models this as two commands — `updateSchedule` and `updateCopy` —
5: 	so the sheet reads an announcement's whole schedule and copy, and saves the
6: 	schedule only when it actually changed: rescheduling swaps the pending job
7: 	and can return advisory `warnings[]`, so a copy-only edit must not pay for
8: 	it. Phoenix owns every refusal (an elapsed first send instant, a schedule
9: 	that sets neither a weekday nor a date, copy that will not render): its
10: 	problem details are shown against the field that caused them.
11: 
12: 	The preview is the API's own renderer for a chosen date. Nothing here
13: 	re-renders tokens locally, so the sheet cannot promise copy that delivery
14: 	would refuse.
15: -->
16: <script lang="ts">
17: import {
18: 	trainingAnnouncementsCreateMutation,
19: 	trainingAnnouncementsListQueryKey,
20: 	trainingAnnouncementsPreviewCopyMutation,
21: 	trainingAnnouncementsUpdateCopyMutation,
22: 	trainingAnnouncementsUpdateScheduleMutation,
23: 	type TrainingAnnouncement,
24: 	type TrainingAnnouncementListResponse,
25: } from "@dhc/api-client";
26: import { createMutation, useQueryClient } from "@tanstack/svelte-query";
27: import { Alert, AlertDescription } from "#lib/components/ui/alert/index.js";
28: import { Button } from "#lib/components/ui/button/index.js";
29: import * as Field from "#lib/components/ui/field/index.js";
30: import { Input } from "#lib/components/ui/input/index.js";
31: import { Label } from "#lib/components/ui/label/index.js";
32: import * as RadioGroup from "#lib/components/ui/radio-group/index.js";
33: import * as Select from "#lib/components/ui/select/index.js";
34: import * as Sheet from "#lib/components/ui/sheet/index.js";
35: import { Switch } from "#lib/components/ui/switch/index.js";
36: import TemplateInput from "#lib/components/ui/template-input.svelte";
37: import DatePicker from "#lib/components/ui/date-picker.svelte";
38: import { TriangleAlert } from "@lucide/svelte";
39: import {
40: 	COPY_PRESETS,
41: 	KIND_CHANNEL_LABELS,
42: 	KIND_LABELS,
43: 	MESSAGE_TOKENS,
44: 	PLACEHOLDER_LABELS,
45: 	TITLE_TOKENS,
46: 	WEEKDAY_OPTIONS,
47: } from "#lib/training-announcements/copy.js";
48: import {
49: 	announcementDraft,
50: 	draftPreviewDate,
51: 	newAnnouncementDraft,
52: 	scheduleChanged,
53: 	type AnnouncementDraft,
54: 	type AnnouncementSave,
55: 	type AnnouncementScheduleType,
56: } from "#lib/training-announcements/announcement.js";
57: import { civilCalendarDate, civilIsoDate } from "#lib/club-calendar.js";
58: import { apiProblem, type ApiFieldMessages } from "#lib/api-error.js";
59: import DiscordMessagePreview from "./DiscordMessagePreview.svelte";
60: 
61: const queryClient = useQueryClient();
62: 
63: let {
64: 	announcement = null,
65: 	today,
66: 	onClose,
67: 	onSaved,
68: }: {
69: 	/** `null` creates a new announcement; an existing row edits it. */
70: 	announcement?: TrainingAnnouncement | null;
71: 	/** Europe/Dublin today as `YYYY-MM-DD`, from the page load. */
72: 	today: string;
73: 	onClose: () => void;
74: 	onSaved: (saved: AnnouncementSave) => void;
75: } = $props();
76: 
77: const editing = $derived(announcement !== null);
78: 
79: let draft = $state<AnnouncementDraft>(
80: 	announcement
81: 		? announcementDraft(announcement, today)
82: 		: newAnnouncementDraft(today),
83: );
84: let previewDate = $state(draftPreviewDate(draft, today));
85: let preview = $state<{ renderedMessage: string; threadName: string } | null>(
86: 	null,
87: );
88: let saveError = $state<string | null>(null);
89: let previewError = $state<string | null>(null);
90: let fieldMessages = $state<ApiFieldMessages[]>([]);
91: 
92: const create = createMutation(() => ({
93: 	...trainingAnnouncementsCreateMutation(),
94: 	/**
95: 	 * The new card appears while the write is still in flight: the draft's
96: 	 * copy is already on screen in the sheet, so the list can show it
97: 	 * immediately behind the form. The temporary row is swapped for
98: 	 * Phoenix's answer on success and removed on refusal, where the sheet
99: 	 * stays open on the field that caused it.
100: 	 */
101: 	onMutate: async (variables) => {
102: 		// An in-flight list read would land on top of the temporary row.
103: 		await queryClient.cancelQueries({
104: 			queryKey: [{ _id: "trainingAnnouncementsList" }],
105: 		});
106: 		const previous =
107: 			queryClient.getQueriesData<TrainingAnnouncementListResponse>({
108: 				queryKey: [{ _id: "trainingAnnouncementsList" }],
109: 			});
110: 		const tempId = `optimistic-${globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.floor(Math.random() * 1_000_000)}`}`;
111: 		const now = new Date().toISOString();
112: 		const optimistic: TrainingAnnouncement = {
113: 			id: tempId,
114: 			kind: variables.body.kind,
115: 			weekday: variables.body.weekday ?? null,
116: 			oneOffDate: variables.body.oneOffDate ?? null,
117: 			postTime: variables.body.postTime,
118: 			title: variables.body.title,
119: 			message: variables.body.message,
120: 			mentionEveryone: variables.body.mentionEveryone,
121: 			enabled: true,
122: 			retired: false,
123: 			firstAttemptedAt: null,
124: 			createdAt: now,
125: 			updatedAt: now,
126: 		};
127: 		queryClient.setQueriesData<TrainingAnnouncementListResponse>(
128: 			{ queryKey: [{ _id: "trainingAnnouncementsList" }] },
129: 			(old) => (old ? { ...old, data: [...old.data, optimistic] } : old),
130: 		);
131: 		return { previous, tempId };
132: 	},
133: 	onError: (_error, _variables, context) => {
134: 		for (const [key, data] of context?.previous ?? [])
135: 			queryClient.setQueryData(key, data);
136: 	},
137: 	onSuccess: (response, _variables, context) => {
138: 		const tempId = context?.tempId;
139: 		if (!tempId) return;
140: 		const saved = response.data.announcement;
141: 		queryClient.setQueriesData<TrainingAnnouncementListResponse>(
142: 			{ queryKey: [{ _id: "trainingAnnouncementsList" }] },
143: 			(old) =>
144: 				old
145: 					? {
146: 							...old,
147: 							data: old.data.map((row) => (row.id === tempId ? saved : row)),
148: 						}
149: 					: old,
150: 		);
151: 	},
152: }));
153: const updateSchedule = createMutation(() =>
154: 	trainingAnnouncementsUpdateScheduleMutation(),
155: );
156: const updateCopy = createMutation(() =>
157: 	trainingAnnouncementsUpdateCopyMutation(),
158: );
159: const previewCopy = createMutation(() =>
160: 	trainingAnnouncementsPreviewCopyMutation(),
161: );
162: 
163: const busy = $derived(
164: 	create.isPending || updateSchedule.isPending || updateCopy.isPending,
165: );
166: 
167: function fieldMessage(field: string): string | undefined {
168: 	return fieldMessages.find((entry) => entry.field === field)?.messages[0];
169: }
170: 
171: function applyKindPreset(kind: AnnouncementDraft["kind"]) {
172: 	draft.kind = kind;
173: 	// Presets exist so the first announcement of a kind is the bot's wording,
174: 	// verbatim. Editing copy afterwards is the committee's business.
175: 	draft.title = COPY_PRESETS[kind].title;
176: 	draft.message = COPY_PRESETS[kind].message;
177: }
178: 
179: function applyScheduleType(scheduleType: AnnouncementScheduleType) {
180: 	draft.scheduleType = scheduleType;
181: 	syncPreviewDate();
182: }
183: 
184: /**
185:  * The slot moved, so the preview defaults back to it. A hand-picked preview
186:  * date is only ever a default — choosing the slot again re-anchors it.
187:  */
188: function syncPreviewDate() {
189: 	previewDate = draftPreviewDate(draft, today);
190: }
191: 
192: /** Exactly one of the two schedule fields is set; the other is cleared. */
193: function scheduleFields() {
194: 	return draft.scheduleType === "weekly"
195: 		? { weekday: draft.weekday, oneOffDate: null, postTime: draft.postTime }
196: 		: { weekday: null, oneOffDate: draft.oneOffDate, postTime: draft.postTime };
197: }
198: 
199: function reportProblem(cause: unknown, fallback: string) {
200: 	const problem = apiProblem(cause);
201: 	saveError = problem?.detail ?? fallback;
202: 	fieldMessages = problem?.fields ?? [];
203: }
204: 
205: function finished(saved: AnnouncementSave) {
206: 	void queryClient.invalidateQueries({
207: 		queryKey: trainingAnnouncementsListQueryKey(),
208: 	});
209: 	onSaved(saved);
210: 	onClose();
211: }
212: 
213: async function save() {
214: 	saveError = null;
215: 	fieldMessages = [];
216: 	try {
217: 		if (!announcement) {
218: 			const response = await create.mutateAsync({
219: 				body: { ...scheduleFields(), ...copyFields(), kind: draft.kind },
220: 			});
221: 			finished(response.data);
222: 			return;
223: 		}
224: 
225: 		// Schedule first: an elapsed slot is refused before any copy is
226: 		// written, so the sheet never half-applies a rejected edit. A copy-only
227: 		// edit has no schedule response, so it carries no warnings.
228: 		let warnings: AnnouncementSave["warnings"] = [];
229: 		if (scheduleChanged(draft, announcement)) {
230: 			const scheduled = await updateSchedule.mutateAsync({
231: 				path: { id: announcement.id },
232: 				body: scheduleFields(),
233: 			});
234: 			warnings = scheduled.data.warnings;
235: 		}
236: 		const copied = await updateCopy.mutateAsync({
237: 			path: { id: announcement.id },
238: 			body: copyFields(),
239: 		});
240: 		finished({ announcement: copied.data, warnings });
241: 	} catch (cause) {
242: 		reportProblem(cause, "Could not save the announcement");
243: 	}
244: }
245: 
246: function copyFields() {
247: 	return {
248: 		title: draft.title,
249: 		message: draft.message,
250: 		mentionEveryone: draft.mentionEveryone,
251: 	};
252: }
253: 
254: async function showPreview() {
255: 	previewError = null;
256: 	try {
257: 		const response = await previewCopy.mutateAsync({
258: 			body: { ...copyFields(), kind: draft.kind, date: previewDate },
259: 		});
260: 		preview = response.data;
261: 	} catch (cause) {
262: 		preview = null;
263: 		previewError = apiProblem(cause)?.detail ?? "Could not preview the message";
264: 	}
265: }
266: </script>
267: 
268: {#snippet fieldError(field: string, errorId?: string)}
269: 	{@const message = fieldMessage(field)}
270: 	{#if message}
271: 		{#if errorId}
272: 			<p
273: 				id={errorId}
274: 				class="flex items-start gap-1.5 text-xs font-semibold text-destructive"
275: 			>
276: 				<TriangleAlert aria-hidden="true" class="mt-0.5 size-3.5 flex-none" />
277: 				{message}
278: 			</p>
279: 		{:else}
280: 			<p class="text-xs font-semibold text-destructive">{message}</p>
281: 		{/if}
282: 	{/if}
283: {/snippet}
284: <Sheet.Root
285: 	open
286: 	onOpenChange={(open) => {
287: 		if (!open) onClose();
288: 	}}
289: >
290: 	<Sheet.Content
291: 		side="right"
292: 		class="w-full overflow-y-auto sm:max-w-2xl"
293: 		data-testid="announcement-sheet"
294: 	>
295: 		<Sheet.Header>
296: 			<Sheet.Title>
297: 				{editing ? "Edit announcement" : "New announcement"}
298: 			</Sheet.Title>
299: 			<Sheet.Description>
300: 				{#if editing}
301: 					Changes apply to future posts. Published posts stay unchanged.
302: 				{:else}
303: 					Choose when to post and write the message.
304: 				{/if}
305: 			</Sheet.Description>
306: 		</Sheet.Header>
307: 		<div class="space-y-6 px-4 pb-2">
308: 			{#if saveError}
309: 				<Alert variant="destructive" data-testid="announcement-sheet-error">
310: 					<AlertDescription>{saveError}</AlertDescription>
311: 				</Alert>
312: 			{/if}
313: 
314: 			<div class="grid gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,20rem)]">
315: 				<div class="space-y-5">
316: 					<!-- Kind and Repeats are RadioGroups, not native radios: the
317: 					     choice drives a side effect (the kind preset, the preview
318: 					     anchor), so the option is the whole clickable card and the
319: 					     dot is a visual. `disabled` on Kind while editing is what
320: 					     stops an existing announcement changing channel. -->
321: 					<Field.Set>
322: 						<Field.Legend class="text-sm font-semibold">Post type</Field.Legend>
323: 						<RadioGroup.Root
324: 							value={draft.kind}
325: 							onValueChange={(value) => {
326: 								if (value) applyKindPreset(value as AnnouncementDraft["kind"]);
327: 							}}
328: 							disabled={editing}
329: 							aria-label="Post type"
330: 							class="grid grid-cols-2 gap-2"
331: 						>
332: 							{#each ["roll_call", "sparring"] as const as kind (kind)}
333: 								<!-- The card is the label and the RadioGroup.Item is its
334: 								     control, so clicking anywhere on the card picks the kind
335: 								     while the button keeps the roving focus and arrow keys.
336: 								     `has-[[data-state=checked]]` is what tints the selected
337: 								     card: the item sets that state, the label only reads it. -->
338: 								<label
339: 									class="flex min-h-11 cursor-pointer items-start justify-between gap-2 rounded-xl border px-3 py-2.5 text-sm font-semibold has-[[data-state=checked]]:border-primary has-[[data-state=checked]]:bg-primary/8 has-[[data-disabled]]:cursor-not-allowed has-[[data-disabled]]:opacity-60"
340: 								>
341: 									<span class="flex min-w-0 flex-col">
342: 										{KIND_LABELS[kind]}
343: 										<span class="text-xs font-medium text-muted-foreground"
344: 											>{KIND_CHANNEL_LABELS[kind]}</span
345: 										>
346: 									</span>
347: 									<RadioGroup.Item
348: 										value={kind}
349: 										class="mt-0.5"
350: 										aria-label={KIND_LABELS[kind]}
351: 									/>
352: 								</label>
353: 							{/each}
354: 						</RadioGroup.Root>
355: 						{#if editing}
356: 							<Field.Description>
357: 								The post type and Discord channel cannot be changed.
358: 							</Field.Description>
359: 						{/if}
360: 						{#if draft.kind === "roll_call"}
361: 							<Field.Description data-testid="holiday-notice-hint">
362: 								On bank holidays a “no training” notice is posted instead, the
363: 								day before and on the day.
364: 							</Field.Description>
365: 						{/if}
366: 					</Field.Set>
367: 
368: 					<Field.Set>
369: 						<Field.Legend class="text-sm font-semibold">Repeats</Field.Legend>
370: 						<RadioGroup.Root
371: 							value={draft.scheduleType}
372: 							onValueChange={(value) => {
373: 								if (value) applyScheduleType(value as AnnouncementScheduleType);
374: 							}}
375: 							aria-label="Repeats"
376: 							class="grid grid-cols-2 gap-2"
377: 						>
378: 							{#each ["weekly", "one_off"] as const as option (option)}
379: 								<label
380: 									class="flex min-h-11 cursor-pointer items-center justify-between gap-2 rounded-xl border px-3 py-2.5 text-sm font-semibold has-[[data-state=checked]]:border-primary has-[[data-state=checked]]:bg-primary/8"
381: 								>
382: 									{option === "weekly" ? "Weekly" : "One-off"}
383: 									<RadioGroup.Item
384: 										value={option}
385: 										aria-label={option === "weekly" ? "Weekly" : "One-off"}
386: 									/>
387: 								</label>
388: 							{/each}
389: 						</RadioGroup.Root>
390: 					</Field.Set>
391: 
392: 					<div class="grid gap-3 sm:grid-cols-2">
393: 						{#if draft.scheduleType === "weekly"}
394: 							<Field.Field>
395: 								<Field.Label for="announcement-weekday">Weekday</Field.Label>
396: 								<Select.Root
397: 									type="single"
398: 									value={String(draft.weekday)}
399: 									onValueChange={(value) => {
400: 										draft.weekday = Number(value);
401: 										syncPreviewDate();
402: 									}}
403: 								>
404: 									<Select.Trigger
405: 										id="announcement-weekday"
406: 										class="w-full"
407: 										aria-label="Weekday"
408: 									>
409: 										{WEEKDAY_OPTIONS.find(
410: 											(option) => option.value === draft.weekday,
411: 										)?.name ?? "Pick a weekday"}
412: 									</Select.Trigger>
413: 									<Select.Content>
414: 										{#each WEEKDAY_OPTIONS as option (option.value)}
415: 											<Select.Item
416: 												value={String(option.value)}
417: 												label={option.name}
418: 											/>
419: 										{/each}
420: 									</Select.Content>
421: 								</Select.Root>
422: 							</Field.Field>
423: 						{:else}
424: 							<Field.Field
425: 								data-invalid={fieldMessage("oneOffDate") !== undefined}
426: 							>
427: 								<Field.Label for="announcement-date">Date</Field.Label>
428: 								<DatePicker
429: 									id="announcement-date"
430: 									dateStyle="medium"
431: 									value={civilCalendarDate(draft.oneOffDate)}
432: 									minValue={civilCalendarDate(today)}
433: 									ariaInvalid={fieldMessage("oneOffDate") !== undefined}
434: 									ariaDescribedby="announcement-date-error"
435: 									onValueChange={(value) => {
436: 										draft.oneOffDate = civilIsoDate(value);
437: 										syncPreviewDate();
438: 									}}
439: 								/>
440: 								{@render fieldError("oneOffDate", "announcement-date-error")}
441: 							</Field.Field>
442: 						{/if}
443: 						<Field.Field data-invalid={fieldMessage("postTime") !== undefined}>
444: 							<Field.Label for="announcement-post-time">Post time</Field.Label>
445: 							<Input
446: 								id="announcement-post-time"
447: 								class="h-11 min-w-0"
448: 								type="time"
449: 								value={draft.postTime}
450: 								aria-invalid={fieldMessage("postTime") !== undefined}
451: 								aria-describedby="announcement-post-time-error"
452: 								oninput={(event) => {
453: 									draft.postTime = event.currentTarget.value;
454: 								}}
455: 							/>
456: 							{@render fieldError("postTime", "announcement-post-time-error")}
457: 						</Field.Field>
458: 					</div>
459: 
460: 					<div class="space-y-1.5">
461: 						<Label for="announcement-title">
462: 							Title <span class="font-normal text-muted-foreground"
463: 								>(also the thread name)</span
464: 							>
465: 						</Label>
466: 						<TemplateInput
467: 							id="announcement-title"
468: 							label="Title"
469: 							maxLength={100}
470: 							bind:value={draft.title}
471: 							invalid={fieldMessage("title") !== undefined}
472: 							tokens={TITLE_TOKENS.map((value) => ({
473: 								value,
474: 								label: PLACEHOLDER_LABELS[value],
475: 							}))}
476: 						/>
477: 						{@render fieldError("title")}
478: 					</div>
479: 
480: 					<div class="space-y-1.5">
481: 						<div class="flex items-center justify-between gap-3">
482: 							<Label for="announcement-message">Message</Label>
483: 							<Button
484: 								variant="link"
485: 								size="sm"
486: 								class="h-auto p-0 text-xs"
487: 								onclick={() => applyKindPreset(draft.kind)}
488: 							>
489: 								Use default message
490: 							</Button>
491: 						</div>
492: 						<TemplateInput
493: 							id="announcement-message"
494: 							label="Message"
495: 							multiline
496: 							bind:value={draft.message}
497: 							invalid={fieldMessage("message") !== undefined}
498: 							tokens={MESSAGE_TOKENS.map((value) => ({
499: 								value,
500: 								label: PLACEHOLDER_LABELS[value],
501: 							}))}
502: 						/>
503: 						{@render fieldError("message")}
504: 						<p class="text-xs text-muted-foreground">
505: 							Placeholders fill in automatically when the post is sent.
506: 						</p>
507: 					</div>
508: 
509: 					<label
510: 						class="flex cursor-pointer items-center justify-between gap-3 rounded-xl border px-3 py-2.5"
511: 					>
512: 						<span class="text-sm">
513: 							<span class="block font-semibold">Notify @everyone</span>
514: 							<span class="text-xs text-muted-foreground"
515: 								>Mention @everyone in the Discord post.</span
516: 							>
517: 						</span>
518: 						<Switch
519: 							checked={draft.mentionEveryone}
520: 							aria-label="Notify @everyone"
521: 							onCheckedChange={(checked) => {
522: 								draft.mentionEveryone = checked;
523: 							}}
524: 						/>
525: 					</label>
526: 				</div>
527: 
528: 				<div class="space-y-2">
529: 					<Field.Field>
530: 						<Field.Label for="announcement-preview-date"
531: 							>Preview date</Field.Label
532: 						>
533: 						<div class="flex gap-2">
534: 							<DatePicker
535: 								id="announcement-preview-date"
536: 								value={civilCalendarDate(previewDate)}
537: 								onValueChange={(value) => {
538: 									previewDate = civilIsoDate(value);
539: 								}}
540: 							/>
541: 							<Button
542: 								variant="outline"
543: 								disabled={previewCopy.isPending}
544: 								onclick={showPreview}
545: 							>
546: 								Preview
547: 							</Button>
548: 						</div>
549: 					</Field.Field>
550: 					{#if preview}
551: 						<DiscordMessagePreview
552: 							channelLabel={KIND_CHANNEL_LABELS[draft.kind]}
553: 							renderedMessage={preview.renderedMessage}
554: 							threadName={preview.threadName}
555: 						/>
556: 					{:else if previewError}
