1: /**
2:  * How a Training Announcement's stored schedule and copy read on screen
3:  * (ALE-330), and the draft the side sheet edits.
4:  *
5:  * This module decides *words and dates*, never whether a save is allowed:
6:  * Phoenix owns the not-elapsed rule, the schedule shape and every lifecycle
7:  * guard, and its 422 problem details are surfaced as they arrive. The only
8:  * schedule knowledge duplicated here is picking a sensible default date for a
9:  * brand-new draft, so opening the sheet cannot immediately fail on an elapsed
10:  * slot.
11:  */
12: import type {
13: 	TrainingAnnouncement,
14: 	TrainingAnnouncementKind,
15: 	TrainingAnnouncementWarning,
16: } from "@dhc/api-client";
17: import { formatCivilDateLong } from "#lib/club-calendar.js";
