20: /** Live, paused by an Announcement Disablement, or terminally retired. */
21: export type AnnouncementLifecycle = "live" | "paused" | "retired";
22: 
23: export const ANNOUNCEMENT_LIFECYCLE_LABELS = {
24: 	live: "Live",
25: 	paused: "Paused",
26: 	retired: "Retired",
27: } satisfies Record<AnnouncementLifecycle, string>;
28: 
29: export type AnnouncementScheduleType = "weekly" | "one_off";
30: 
31: /**
32:  * What one committed write produced: the announcement as Phoenix now sees it,
33:  * plus any advisory warnings. `updateCopy`, the lifecycle commands and a
34:  * copy-only edit have no schedule response, so their `warnings` is empty.
35:  */
36: export type AnnouncementSave = {
37: 	announcement: TrainingAnnouncement;
38: 	warnings: TrainingAnnouncementWarning[];
39: };
