56: export function announcementLifecycle(
57: 	announcement: TrainingAnnouncement,
58: ): AnnouncementLifecycle {
59: 	if (announcement.retired) return "retired";
60: 	return announcement.enabled ? "live" : "paused";
61: }
62: 
63: /** `HH:MM:SS` from Phoenix as the `HH:MM` an `<input type="time">` wants. */
64: export function postTimeLabel(postTime: string): string {
65: 	return postTime.slice(0, 5);
66: }
67: 
68: function civilDate(isoDate: string): Date {
69: 	// Anchored at UTC midnight so the formatted weekday never shifts with the
70: 	// reader's own time zone.
71: 	return new Date(`${isoDate}T00:00:00Z`);
72: }
73: 
74: function isoWeekday(isoDate: string): number {
75: 	const day = civilDate(isoDate).getUTCDay();
76: 	return day === 0 ? 7 : day;
77: }
78: 
79: function addDays(isoDate: string, days: number): string {
80: 	const date = civilDate(isoDate);
81: 	date.setUTCDate(date.getUTCDate() + days);
82: 	return date.toISOString().slice(0, 10);
83: }
84: 
85: /**
86:  * The next occurrence date of a weekly announcement: today when today is the
87:  * chosen weekday, otherwise the first such day after it. Which of those slots
88:  * has already elapsed today is Phoenix's to decide.
89:  */
90: export function nextOccurrenceDate(weekday: number, today: string): string {
91: 	const delta = (weekday - isoWeekday(today) + 7) % 7;
92: 	return addDays(today, delta);
93: }
94: 
95: export function scheduleLabel(announcement: TrainingAnnouncement): string {
96: 	const time = postTimeLabel(announcement.postTime);
97: 	if (announcement.weekday !== null) {
98: 		return `Every ${WEEKDAY_NAMES[announcement.weekday]} at ${time}`;
99: 	}
100: 	const date = announcement.oneOffDate;
101: 	return date
102: 		? `One-off on ${formatCivilDateLong(date)} at ${time}`
103: 		: `One-off at ${time}`;
104: }
105: 
106: /**
107:  * Why `DELETE /training-announcements/:id` is refused, or `undefined` when it
108:  * is allowed. Phoenix answers an attempted announcement with `attempted`; the
109:  * UI refuses it first so the card can explain the retire-only rule.
110:  */
111: export function deleteBlockedReason(
112: 	announcement: TrainingAnnouncement,
113: ): string | undefined {
114: 	if (announcement.retired) {
115: 		return "Retired announcements keep their history and cannot be deleted.";
116: 	}
117: 	if (announcement.firstAttemptedAt !== null) {
118: 		return "Posting has already been attempted. Retire this announcement to keep its history.";
119: 	}
120: 	return undefined;
121: }
122: 
123: export function newAnnouncementDraft(today: string): AnnouncementDraft {
124: 	const preset = COPY_PRESETS.roll_call;
125: 	return {
126: 		kind: "roll_call",
127: 		scheduleType: "weekly",
128: 		// The next weekday rather than today's: today's slot may already have
129: 		// elapsed, and a new draft should not open on a guaranteed rejection.
130: 		weekday: nextOccurrenceWeekday(today),
131: 		oneOffDate: addDays(today, 1),
132: 		postTime: "10:00",
133: 		title: preset.title,
134: 		message: preset.message,
135: 		mentionEveryone: true,
136: 	};
137: }
138: 
139: function nextOccurrenceWeekday(today: string): number {
140: 	return (isoWeekday(today) % 7) + 1;
141: }
142: 
143: export function announcementDraft(
144: 	announcement: TrainingAnnouncement,
145: 	today: string,
146: ): AnnouncementDraft {
147: 	const scheduleType: AnnouncementScheduleType =
148: 		announcement.weekday !== null ? "weekly" : "one_off";
149: 	return {
150: 		kind: announcement.kind,
151: 		scheduleType,
152: 		weekday: announcement.weekday ?? nextOccurrenceWeekday(today),
153: 		oneOffDate: announcement.oneOffDate ?? addDays(today, 1),
154: 		postTime: postTimeLabel(announcement.postTime),
155: 		title: announcement.title,
156: 		message: announcement.message,
157: 		mentionEveryone: announcement.mentionEveryone,
158: 	};
159: }
160: 
161: /** The date the sheet previews: the one-off's date, or the next weekly slot. */
162: export function draftPreviewDate(
163: 	draft: AnnouncementDraft,
164: 	today: string,
165: ): string {
166: 	return draft.scheduleType === "one_off"
167: 		? draft.oneOffDate
168: 		: nextOccurrenceDate(draft.weekday, today);
169: }
170: 
171: /**
172:  * Whether saving this draft needs the schedule call. The two commands are
173:  * separate because the API models schedule and copy as separate writes, so an
174:  * unchanged schedule must not reschedule an announcement (and cannot produce
175:  * the advisory warnings a schedule edit may return).
176:  */
177: export function scheduleChanged(
178: 	draft: AnnouncementDraft,
179: 	announcement: TrainingAnnouncement,
180: ): boolean {
181: 	const postTime = postTimeLabel(announcement.postTime);
182: 	if (draft.scheduleType === "weekly") {
183: 		return (
184: 			draft.weekday !== announcement.weekday ||
185: 			draft.postTime !== postTime ||
186: 			announcement.oneOffDate !== null
187: 		);
188: 	}
189: 	return (
190: 		draft.oneOffDate !== (announcement.oneOffDate ?? "") ||
191: 		draft.postTime !== postTime ||
192: 		announcement.weekday !== null
193: 	);
194: }
195: 
196: /** Advisory `warnings[]` from create/updateSchedule, in committee words. */
197: export function warningMessages(
198: 	warnings: readonly TrainingAnnouncementWarning[],
199: ): string[] {
200: 	return warnings.map((warning) =>
201: 		warning === "slot_collision"
202: 			? "Another announcement is scheduled for the same time. Review the schedules to avoid duplicate posts."
203: 			: "The schedule has changed. Review skipped dates and text changes; they may apply to different posts now.",
204: 	);
205: }

