272: function renderRail() {
273: 	const queryClient = new QueryClient({
274: 		defaultOptions: {
275: 			queries: { retry: false, staleTime: Infinity, refetchOnMount: false },
276: 			mutations: { retry: false },
277: 		},
278: 	});
279: 	return render(AnnouncementsRailTestWrapper, { today: TODAY, queryClient });
280: }
