282: function callBody(
283: 	api: AnnouncementApi,
284: 	method: string,
285: 	path: string,
286: ): Call["body"] {
287: 	const call = api.calls.find(
288: 		(entry) => entry.method === method && entry.url.includes(path),
289: 	);
290: 	if (!call) {
291: 		throw new Error(
292: 			`no ${method} call to ${path}: ${JSON.stringify(api.calls)}`,
293: 		);
294: 	}
295: 	return call.body;
296: }
