29: export type AnnouncementScheduleType = "weekly" | "one_off";
30: 
31: /**
32:  * What one committed write produced: the announcement as Phoenix now sees it,
33:  * plus any advisory warnings. `updateCopy`, the lifecycle commands and a
34:  * copy-only edit have no schedule response, so their `warnings` is empty.
35:  */
36: export type AnnouncementSave = {
