41: /** The side sheet's editable copy of one announcement's schedule and copy. */
42: export type AnnouncementDraft = {
43: 	kind: TrainingAnnouncementKind;
44: 	scheduleType: AnnouncementScheduleType;
45: 	/** ISO weekday, 1 (Monday) to 7 (Sunday). */
46: 	weekday: number;
47: 	/** Dublin civil date as `YYYY-MM-DD`. */
48: 	oneOffDate: string;
49: 	/** Dublin civil time as `HH:MM`. */
