148: 		announcement.weekday !== null ? "weekly" : "one_off";
149: 	return {
150: 		kind: announcement.kind,
151: 		scheduleType,
152: 		weekday: announcement.weekday ?? nextOccurrenceWeekday(today),
153: 		oneOffDate: announcement.oneOffDate ?? addDays(today, 1),
154: 		postTime: postTimeLabel(announcement.postTime),
155: 		title: announcement.title,
