180: 						data: url.includes("includeRetired=true")
181: 							? rows
182: 							: rows.filter((row) => !row.retired),
183: 					});
184: 				}
185: 				if (method === "POST" && url.endsWith("/preview-copy")) {
186: 					return json({ data: preview });
187: 				}
188: 				if (method === "POST" && url.endsWith("/training-announcements")) {
189: 					if (deferCreate) {
190: 						// The executor runs synchronously, so the releaser is
191: 						// set before the recorded call is visible to the test.
192: 						await new Promise<void>((resolve) => {
193: 							releaseCreate = resolve;
194: 						});
195: 					}
196: 					const created = announcement({
197: 						...(body ?? {}),
198: 						id: SPARRING_ID,
199: 					});
200: 					rows = [...rows, created];
201: 					return json({ data: { announcement: created, warnings } }, 201);
202: 				}
203: 				if (method === "POST" && url.includes("/disable")) {
204: 					return json({ data: toggle(url, "disable") });
205: 				}
206: 				if (method === "POST" && url.includes("/enable")) {
207: 					return json({ data: toggle(url, "enable") });
208: 				}
209: 				if (method === "POST" && url.includes("/retire")) {
210: 					return json({ data: toggle(url, "retire") });
211: 				}
212: 				if (method === "DELETE" && url.includes("/training-announcements/")) {
213: 					const id = url.split("/").at(-1) ?? "";
214: 					rows = rows.filter((row) => row.id !== id);
215: 					return new Response(null, { status: 204 });
216: 				}
217: 				if (method === "PUT" && url.includes("/schedule")) {
218: 					return json({
219: 						data: { announcement: applyUpdate(url, body ?? {}), warnings },
220: 					});
221: 				}
222: 				if (method === "PUT" && url.includes("/copy")) {
223: 					return json({ data: applyUpdate(url, body ?? {}) });
224: 				}
225: 				return json({ errors: { detail: `${method} ${url}` } }, 404);
226: 			},
227: 		},
228: 	});
229: 
230: 	function idFrom(url: string): string {
231: 		return url.split("/").at(-2) ?? "";
232: 	}
233: 
234: 	function applyUpdate(
235: 		url: string,
236: 		changes: Partial<TrainingAnnouncement>,
237: 	): TrainingAnnouncement {
238: 		const id = idFrom(url);
239: 		rows = rows.map((row) => (row.id === id ? { ...row, ...changes } : row));
240: 		const updated = rows.find((row) => row.id === id);
241: 		if (!updated) throw new Error(`no announcement ${id}`);
242: 		return updated;
243: 	}
244: 
245: 	function toggle(
246: 		url: string,
247: 		action: "disable" | "enable" | "retire",
248: 	): TrainingAnnouncement {
249: 		const id = idFrom(url);
250: 		if (action === "retire") {
251: 			rows = rows.map((row) =>
252: 				row.id === id ? { ...row, retired: true } : row,
253: 			);
254: 		} else {
255: 			rows = rows.map((row) =>
256: 				row.id === id ? { ...row, enabled: action === "enable" } : row,
257: 			);
258: 		}
259: 		const updated = rows.find((row) => row.id === id);
260: 		if (!updated) throw new Error(`no announcement ${id}`);
261: 		return updated;
262: 	}
263: 
264: 	return {
265: 		calls,
266: 		rows: () => rows,
267: 		releaseCreate: () => releaseCreate?.(),
268: 		releaseCommand: () => releaseCommand?.(),
269: 	};
270: }
