303: /**
304:  * Pick a Dublin date through the shared date picker the way a reader does: open
305:  * the popover, then click the day cell. Replaces the `fill()` these tests used
306:  * on a native `type="date"` input, which no longer exists.
307:  */
308: async function pickDate(
309: 	screen: Awaited<ReturnType<typeof renderRail>>,
310: 	label: string,
311: 	isoDate: string,
312: ) {
313: 	// Scoped to the button's exact accessible name: "Date" is a prefix of
314: 	// "Preview date", and both are date pickers on this form.
315: 	await screen.getByRole("button", { name: label, exact: true }).click();
316: 	// bits-ui labels each day button with its full date, which disambiguates a
317: 	// day number that an adjacent month repeats.
318: 	await screen.getByRole("button", { name: dayLabel(isoDate) }).click();
319: }
320: 
321: /** The accessible name bits-ui gives a `Calendar` day button. */
322: function dayLabel(isoDate: string): string {
323: 	const [year, month, day] = isoDate.split("-").map(Number);
324: 	// SAFETY: every caller passes a `YYYY-MM-DD` literal, so the parts are
325: 	// numbers; `!` keeps the destructuring honest without a runtime guard.
326: 	const date = new Date(year!, month! - 1, day!);
327: 	return new Intl.DateTimeFormat("en-US", {
328: 		weekday: "long",
329: 		month: "long",
330: 		day: "numeric",
331: 		year: "numeric",
332: 	}).format(date);
333: }
